'use strict';

// User-approved contract: restore the complete three original documents.
// Expected prose is frozen from commit 81a73dc, not generated by current code.
// Corrected source findings belong in those same sentence/field positions.
const test = require('node:test');
const assert = require('node:assert/strict');
const { loadApp, toText } = require('./app-harness.cjs');
const reference = require('./fixtures/original-three-documents.json');

const compact = value => String(value).replace(/\s+/g, ' ').trim();
const currentNames = ['summary', 'consultation', 'discharge'];
const forbiddenAdditions = /@ Clinical records|Additional source records|Recorded physical examination:|The physical examination record stated|DDH risk assessment:|Hip examination:|DDH compression assessment:|Sepsis evaluation plan selected|Selected transfer plan:|Blood glucose monitoring plan:|Treatment and prophylaxis administration|Risk factors and examination findings|(?:not|were not) documented\b/i;

function originalWithoutNegativeHIV(text) {
  return String(text).replace(/HIV\(-\),\s*/g, '').replace(/,\s*HIV\(-\)/g, '').replace(/,\s*HIV(?=[,)])/g, '');
}

function configure(app, selectors = []) {
  for (const selector of selectors) {
    const el = app.document.querySelector(selector);
    assert.ok(el, `original control still exists: ${selector}`);
    if (el.type === 'radio') app.document.querySelectorAll(`input[name="${el.name}"]`).forEach(radio => { radio.checked = false; });
    el.checked = true;
  }
}

function specimen(source, controls = [], campus = 'tpc') {
  const app = loadApp(campus);
  configure(app, controls);
  const data = app.parse(source);
  const pe = app.context.getPEFindings();
  const html = app.render(data, pe);
  const outputs = Object.fromEntries(Object.entries(html).map(([name, value]) => [name, toText(value)]));
  assert.equal(app.errors.length, 0);
  return { app, data, pe, html, outputs };
}

for (const group of [...new Set(reference.cases.map(item => item.group))]) {
  test(`OT: full original admission, consultation and discharge text for ${group} controls`, () => {
    for (const item of reference.cases.filter(item => item.group === group)) {
      const { app, data, pe, outputs } = specimen(item.source, item.controls, item.campus);
      for (const name of currentNames) {
        assert.equal(compact(outputs[name]), compact(originalWithoutNegativeHIV(item.expected[name])),
          `${item.id} ${name}: entire document must retain the original prose; only nonpositive HIV is omitted`);
        assert.doesNotMatch(outputs[name], forbiddenAdditions, `${item.id} ${name}: no new explanatory/source/plan blocks`);
      }
      assert.equal(toText(app.context.generateNarrativeReview(data, pe, 'summary')), '');
      assert.equal(toText(app.context.generateNarrativeReview(data, pe, 'discharge')), '');
    }
  });
}

test('OT: sparse data keeps original consultation fields without generating a missing-data or source appendix', () => {
  const { data, outputs } = specimen('BW 3200 gm');
  assert.equal(data.gaWeeks, null);
  assert.equal(data.bw, '3200');
  assert.doesNotMatch(outputs.diagnosis, /# Term infant|, AGA\b/);
  assert.match(outputs.consultation, /^Dear Dr,\n/);
  for (const field of ["@ Maternal condition:", 'Maternal blood type:', 'Serology:', 'GBS:', 'GDM:', 'Prenatal steroid use:', 'Prenatal antibiotics:', "@ Newborn's condition:", 'Apgar score:', 'Activity:', 'Muscle tone:', 'Respiration:', 'High risk neonatal critical care:']) {
    assert.equal(outputs.consultation.split(field).length - 1, 1, `retain original field once: ${field}`);
  }
  assert.match(outputs.consultation, /Therefore, (?:he|she|the infant) was transferred to BR for further evaluation and treatment\.$/);
  for (const name of currentNames) assert.doesNotMatch(outputs[name], forbiddenAdditions, name);
  assert.doesNotMatch(outputs.summary, /via NSD|39\+0|female infant|Screening for DDH risk factors and physical signs was negative/,
    'restoring prose does not reinstate unsupported parsed defaults');
});

test('OT: additional clinical-source archives stay parsed without appearing as new consultation or diagnosis sections', () => {
  const plain = reference.cases.find(item => item.id === 'routine-taipei').source;
  const source = `${plain}\nNursery course: feeding was well tolerated at 48 hours of age.\nLaboratory: blood glucose 61 mg/dL at 4 hours of age.\nEducation: caregivers were counseled about feeding and jaundice.\nDischarged home in stable condition at 72 hours of age.`;
  const { app, data, outputs } = specimen(source);
  const records = app.context.getClinicalSourceRecords(data);
  assert.ok(records.course.some(line => /48 hours/.test(line)), 'the course parser still retains its source');
  assert.ok(records.labs.some(line => /61 mg\/dL/.test(line)), 'the laboratory parser still retains its source');
  const baseline = specimen(plain).outputs;
  assert.equal(compact(outputs.consultation), compact(baseline.consultation),
    'a later BR course has no original consultation slot; do not append a clinical record catalog');
  assert.equal(compact(outputs.diagnosis), compact(baseline.diagnosis),
    'course/education/follow-up are not a diagnosis archive');
  assert.doesNotMatch(outputs.summary, /48 hours|61 mg\/dL|72 hours|counseled about feeding/);
  for (const name of currentNames) assert.doesNotMatch(outputs[name], forbiddenAdditions, name);
});

test('OT: new source findings use the original PE sentence and retain grade, side and DDH qualifiers', () => {
  const source = reference.cases.find(item => item.id === 'routine-taipei').source
    .replace('DDH risk factors: negative', 'DDH risk factors:\nFamily Hx (+)\nOligohydramnios (+)')
    .replace('子宮內壓迫徵象: negative', '子宮內壓迫徵象:\n斜頸 (+)')
    .replace('Hip PE: negative', 'Hip PE: Barlow(+), Ortolani(-)')
    .replace('PE: no gross anomalies.', 'PE: grade 2/6 systolic murmur at left sternal border; Left undescended testis(+)');
  const { data, outputs } = specimen(source);
  assert.deepEqual(Array.from(data.ddhRisk), ['family history of DDH', 'oligohydramnios']);
  assert.deepEqual(Array.from(data.compressionSigns), ['torticollis']);
  assert.deepEqual(Array.from(data.ddhPe), ["positive Barlow's sign"]);
  for (const name of currentNames) {
    for (const fact of [/family history of DDH/i, /oligohydramnios/i, /torticollis/i, /Barlow/i, /2\/6/, /left sternal border/i, /left undescended testis|undescended testis[^.]*\(lt\)/i]) {
      assert.match(outputs[name], fact, `${name}: corresponding recorded finding ${fact}`);
    }
    assert.doesNotMatch(outputs[name], /physical examination of the hips was unremarkable|Screening for DDH risk factors and physical signs was negative/);
    assert.doesNotMatch(outputs[name], forbiddenAdditions, name);
  }
  assert.match(outputs.summary, /On physical examination,/);
  assert.match(outputs.consultation, /His physical examination was also notable for /);
  assert.equal(outputs.consultation.split('physical examination was also notable for').length - 1, 1,
    'all new findings use one original PE sentence');
  assert.match(outputs.discharge, /Due to identified DDH risk factors including /);
  assert.doesNotMatch(outputs.diagnosis, /Risk factors|family history|oligohydramnios|Additional source records|^# Positive Ortolani/im);
});

test('OT: unknown and conflicting DDH stay qualified within original prose and never become a normal screen or diagnosis', () => {
  const source = reference.cases.find(item => item.id === 'routine-taipei').source
    .replace('DDH risk factors: negative', 'DDH risk factors: Breech(+), Breech(-), Family Hx(?)')
    .replace('子宮內壓迫徵象: negative', '子宮內壓迫徵象: 斜頸(?)')
    .replace('Hip PE: negative', 'Hip PE: Barlow(+) or Ortolani(+)')
    .replace('PE: no gross anomalies.', 'PE: Heart murmur(?)');
  const { data, outputs } = specimen(source);
  assert.equal(data.ddhRisk.length, 0);
  assert.equal(data.compressionSigns.length, 0);
  assert.equal(data.ddhPe.length, 0);
  for (const name of currentNames) {
    assert.match(outputs[name], /Breech\(\+\)[\s\S]*Breech\(-\)/i);
    assert.match(outputs[name], /Barlow\(\+\) or Ortolani\(\+\)/i);
    assert.doesNotMatch(outputs[name], /Screening for DDH risk factors and physical signs was negative|physical examination of the hips was unremarkable|positive Barlow's sign|positive Ortolani's sign/i);
    assert.doesNotMatch(outputs[name], forbiddenAdditions, name);
  }
  assert.doesNotMatch(outputs.diagnosis, /^# (?:Heart murmur|Positive .* sign|Suspected developmental dysplasia|Breech)/im);
});

test('OT: ordinary negative PE siblings keep original normal fields without becoming a new findings catalog', () => {
  const source = reference.cases.find(item => item.id === 'routine-taipei').source
    .replace('PE: no gross anomalies.', 'PE: Heart murmur(+), grade 2/6 at left sternal border; Jaundice(-); Cyanosis(-); Hypotonia(-)');
  const { data, outputs } = specimen(source);
  for (const fact of [/Jaundice\(-\)/, /Cyanosis\(-\)/, /Hypotonia\(-\)/]) assert.match(data.sourcePE, fact);
  for (const name of currentNames) {
    assert.equal((outputs[name].match(/heart murmur/gi) || []).length, 1, `${name}: positive finding once`);
    assert.match(outputs[name], /2\/6[^.]*left sternal border/i);
    assert.doesNotMatch(outputs[name], /Jaundice\(-\)|no jaundice|Hypotonia\(-\)|Cyanosis\(-\)|DDH risk assessment|Recorded physical examination/i,
      `${name}: ordinary negative siblings do not create a new catalog`);
  }
  assert.match(outputs.consultation, /Activity: fair\. Muscle tone: normal\. No cyanosis\./);
});

test('OT: source cyanosis and hypotonia replace the corresponding original inline normal descriptions', () => {
  const source = reference.cases.find(item => item.id === 'routine-taipei').source
    .replace('PE: no gross anomalies.', 'PE: Cyanosis(+); Hypotonia(+)');
  const { outputs } = specimen(source);
  assert.match(outputs.consultation, /Activity: not doing well\. Muscle tone: decreased\. General cyanosis\./);
  assert.doesNotMatch(outputs.consultation, /No cyanosis|Muscle tone: normal|Cyanosis\(\+\).*physical examination/i);
  assert.doesNotMatch(outputs.diagnosis, /No cyanosis|normal tone/i);
});
